#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

void bitAdd(vector<long long>& t, long long i, long long x) {
    long long n = (long long)t.size() - 1;
    for (; i <= n; i += i & -i) t[i] += x;
}

long long bitSum(const vector<long long>& t, long long i) {
    long long s = 0;
    for (; i > 0; i -= i & -i) s += t[i];
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long q;
    cin >> q;
